solution.code:
const messages = { en: { greeting: "Welcome" }, es: { greeting: "Bienvenida" } };
function App() {
  const [locale, setLocale] = useState("en");
  return <div><label>Language <select value={locale} onChange={e => setLocale(e.target.value)}><option value="en">English</option><option value="es">Español</option></select></label><h1>{messages[locale].greeting}</h1></div>;
}
